CREATE TABLE companies (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, inn VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL,
 operating_months INTEGER NOT NULL CHECK (operating_months>=0), cash_balance_rub BIGINT NOT NULL CHECK(cash_balance_rub>=0),
 existing_debt_monthly_rub BIGINT NOT NULL CHECK(existing_debt_monthly_rub>=0), late_payments_last12m INTEGER NOT NULL CHECK(late_payments_last12m>=0),
 tax_debt_rub BIGINT NOT NULL CHECK(tax_debt_rub>=0), is_active BOOLEAN NOT NULL, financials_version BIGINT NOT NULL DEFAULT 0, version BIGINT NOT NULL DEFAULT 0
);
CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(255) NOT NULL,role VARCHAR(255) NOT NULL CHECK(role IN ('ENTREPRENEUR','BANK_OFFICER')),company_id BIGINT REFERENCES companies(id));
CREATE TABLE monthly_financials (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL REFERENCES companies(id), month VARCHAR(255) NOT NULL, revenue_rub BIGINT NOT NULL CHECK(revenue_rub>=0),operating_expenses_rub BIGINT NOT NULL CHECK(operating_expenses_rub>=0), UNIQUE(company_id,month));
CREATE TABLE credit_products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(255) NOT NULL,annual_rate_pct NUMERIC(38,2) NOT NULL CHECK(annual_rate_pct>=0),min_amount_rub BIGINT NOT NULL CHECK(min_amount_rub>0),max_amount_rub BIGINT NOT NULL CHECK(max_amount_rub>=min_amount_rub),allowed_terms_months VARCHAR(255) NOT NULL);
CREATE TABLE loan_applications (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,company_id BIGINT NOT NULL REFERENCES companies(id),created_by_user_id BIGINT NOT NULL REFERENCES users(id),product_id BIGINT NOT NULL REFERENCES credit_products(id),requested_amount_rub BIGINT NOT NULL CHECK(requested_amount_rub>0),term_months INTEGER NOT NULL CHECK(term_months>0),purpose VARCHAR(255) NOT NULL CHECK(purpose IN ('EQUIPMENT','WORKING_CAPITAL','EXPANSION')),
 projected_revenue_uplift_monthly_rub BIGINT NOT NULL CHECK(projected_revenue_uplift_monthly_rub>=0), uplift_start_month INTEGER NOT NULL CHECK(uplift_start_month BETWEEN 1 AND 12),status VARCHAR(255) NOT NULL CHECK(status IN ('DRAFT','CHECKING','NEEDS_INFO','UNDER_REVIEW','OFFERED','DECLINED','ACCEPTED','SIMULATED_ISSUED')), created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,submitted_at TIMESTAMP WITH TIME ZONE,status_comment TEXT,active_snapshot_id BIGINT,version BIGINT NOT NULL DEFAULT 0
);
CREATE INDEX idx_application_company ON loan_applications(company_id);
CREATE INDEX idx_application_status ON loan_applications(status);
CREATE INDEX idx_application_created ON loan_applications(created_at);
CREATE TABLE application_snapshots (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,application_id BIGINT NOT NULL REFERENCES loan_applications(id),company_and_financials_snapshot_json TEXT NOT NULL,product_snapshot_json TEXT NOT NULL,engine_request_json TEXT NOT NULL,captured_at TIMESTAMP WITH TIME ZONE NOT NULL);
ALTER TABLE loan_applications ADD CONSTRAINT fk_active_snapshot FOREIGN KEY(active_snapshot_id) REFERENCES application_snapshots(id);
CREATE TABLE scoring_results (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,application_id BIGINT NOT NULL REFERENCES loan_applications(id),snapshot_id BIGINT NOT NULL UNIQUE REFERENCES application_snapshots(id),score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 1000),risk_level VARCHAR(255) NOT NULL,recommendation VARCHAR(255) NOT NULL,dscr NUMERIC(38,2) NOT NULL,monthly_payment_rub BIGINT NOT NULL CHECK(monthly_payment_rub>=0),factors_json TEXT NOT NULL,full_result_json TEXT NOT NULL,evaluated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE credit_decisions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,application_id BIGINT NOT NULL REFERENCES loan_applications(id),decision VARCHAR(255) NOT NULL,comment TEXT NOT NULL,offered_amount_rub BIGINT,offered_term_months INTEGER,offered_annual_rate_pct NUMERIC(38,2),decided_by_user_id BIGINT NOT NULL REFERENCES users(id),decided_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE application_status_history (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,application_id BIGINT NOT NULL REFERENCES loan_applications(id),from_status VARCHAR(255),to_status VARCHAR(255) NOT NULL,actor_role VARCHAR(255) NOT NULL,comment TEXT,changed_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_history_application ON application_status_history(application_id,id);
CREATE INDEX idx_snapshot_application ON application_snapshots(application_id,id);
CREATE INDEX idx_score_application ON scoring_results(application_id,id);
CREATE INDEX idx_decision_application ON credit_decisions(application_id,id);
